def dependency_setup(install=False):
    try:
        import numpy
        from scipy.stats import t
    except ImportError:
        if not install:raise SystemExit('NumPy and SciPy required. Run with --install-deps.')
        subprocess.run([sys.executable,'-m','pip','install','numpy','scipy'],check=True)
    global np,student_t
    import numpy as np
    from scipy.stats import t as student_t

def canonical(x):
    def cast(v):
        if isinstance(v,np.generic):return v.item()
        if isinstance(v,np.ndarray):return v.tolist()
        if isinstance(v,Path):return str(v)
        raise TypeError(type(v).__name__)
    return json.dumps(x,sort_keys=True,separators=(',',':'),allow_nan=False,default=cast).encode()

def digest(x):return hashlib.sha256(x if isinstance(x,bytes) else canonical(x)).hexdigest()
def state_fingerprint(obj):
    def norm(x):
        if isinstance(x,np.ndarray):return ['ndarray',x.dtype.str,list(x.shape),digest(x.tobytes())]
        if isinstance(x,np.generic):return norm(x.item())
        if isinstance(x,np.random.Generator):return ['rng',norm(x.bit_generator.state)]
        if isinstance(x,(bytes,bytearray)):return ['bytes',bytes(x).hex()]
        if isinstance(x,dict):return ['dict',[[norm(k),norm(v)] for k,v in x.items()]]
        if isinstance(x,(list,tuple,collections.deque)):return [type(x).__name__,[norm(v) for v in x]]
        if isinstance(x,set):return ['set',sorted((norm(v) for v in x),key=repr)]
        if x is None or isinstance(x,(str,int,bool)):return x
        if isinstance(x,float):return ['float',x.hex()]
        if callable(x):return ['callable',x.__module__,x.__qualname__]
        if hasattr(x,'__dict__'):return [type(x).__module__,type(x).__name__,norm(x.__dict__)]
        raise TypeError('Unsupported state member '+type(x).__name__)
    return digest(norm(obj))
def atomic_bytes(path,data):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_name(path.name+f'.tmp-{os.getpid()}')
    with tmp.open('wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
    os.replace(tmp,path)
def write_json(path,x):atomic_bytes(path,json.dumps(json.loads(canonical(x)),indent=2).encode()+b'\n')

def load_modules():
    if MODULES:return MODULES
    def load(name,key,extra=None):
        text=zlib.decompress(base64.b85decode(PAYLOADS[key]['data'])).decode()
        assert digest(text.encode())==PAYLOADS[key]['sha256']
        mod=types.ModuleType(name);mod.__file__=str(Path(__file__).resolve())
        mod.__dict__.update(extra or {});sys.modules[name]=mod
        if key=='claude':
            assert text.count('V39 = _load_v39()')==1
            text=text.replace('V39 = _load_v39()','V39 = M')
        exec(compile(text,'<embedded:'+key+'>','exec'),mod.__dict__)
        mod.np=np;mod.student_t=student_t
        return mod
    M=load('v41_legacy','legacy')
    C=load('v41_claude','claude',{'M':M})
    U=load('v41_utilitysubstrate','utilitysubstrate')
    extra=dict(M=M,C=C,U=U,np=np)
    for key in ('hybrid','utility','stationarity'):
        MODULES[key]=load('v41_'+key,key,extra)
    return MODULES

def pack_state(state,identity):
    payload=zlib.compress(pickle.dumps(state,protocol=5),level=1)
    header=canonical({'identity':identity,'payload_sha256':digest(payload),'format':1})
    return struct.pack('>Q',len(header))+header+payload
def unpack_state(data,identity):
    if len(data)<8:raise ValueError('Truncated checkpoint')
    size=struct.unpack('>Q',data[:8])[0]
    if size>1000000 or size>len(data)-8:raise ValueError('Invalid checkpoint header')
    h=json.loads(data[8:8+size]);payload=data[8+size:]
    if h.get('identity')!=identity:raise ValueError('Checkpoint belongs to a different source or plan')
    if h.get('format')!=1 or h.get('payload_sha256')!=digest(payload):raise ValueError('Corrupted checkpoint')
    # Only load this runner's own checksummed local checkpoints, never external pickle files.
    return pickle.loads(zlib.decompress(payload))

def save_checkpoint(path,state,identity):
    path=Path(path)
    encoded=pack_state(state,identity)
    if path.exists():atomic_bytes(path.with_suffix('.previous'),path.read_bytes())
    atomic_bytes(path,encoded)
def read_checkpoint(path,identity):
    path=Path(path)
    if path.exists():return unpack_state(path.read_bytes(),identity)
    previous=path.with_suffix('.previous')
    if previous.exists():return unpack_state(previous.read_bytes(),identity)
    return None

def completed_read(path,identity):
    x=json.loads(Path(path).read_text())
    if x.get('identity')!=identity or x.get('sha256')!=digest(x.get('data')):
        raise ValueError('Corrupt or mismatched result: '+str(path))
    return x['data']

def completed_write(path,identity,data):
    # Normalize integer mapping keys and NumPy values before hashing the JSON
    # representation that a later process will actually read.
    data=json.loads(canonical(data))
    write_json(path,{'identity':identity,'sha256':digest(data),'data':data})

def status_extract(state):
    out={}
    for key in ('cursor','record','position','pos','phase','stage','done','byte_events','train_cursor','eval_cursor'):
        val=state.get(key) if isinstance(state,dict) else None
        if isinstance(val,(str,int,float,bool)):out[key]=val
    if isinstance(state,dict) and 'stream' in state:
        out['total_records']=len(state['stream']['rows'])+state.get('warm_count',0)
    elif isinstance(state,dict) and 'train' in state:
        out['phase_records']=len(state['train']) if state.get('phase')=='train' else len(state['future'])
    return out

def worker(job):
    dependency_setup();mods=load_modules()
    name,seed,cfg,out,plan_id,chunk,stop_after=job
    root=Path(out);stem=f'{name}_{seed}';cp=root/'checkpoints'/(stem+'.checkpoint')
    rp=root/'completed'/(stem+'.json');identity={'plan':plan_id,'experiment':name,'seed':seed,'config':cfg}
    if rp.exists():
        completed_read(rp,identity);return {'job':stem,'status':'reused'}
    if (root/'STOP_REQUESTED').exists():return {'job':stem,'status':'not_started'}
    saved=read_checkpoint(cp,identity)
    resumed=saved is not None
    if saved is None:
        saved={'state':mods[name].init_state(seed,cfg),'blocks':0,'active_seconds':0.}
        save_checkpoint(cp,saved,identity)
    started=time.monotonic();local_blocks=0
    while True:
        if (root/'STOP_REQUESTED').exists():
            return {'job':stem,'status':'paused','active_seconds':saved['active_seconds']}
        t=time.monotonic()
        done=bool(mods[name].step(saved['state'],cfg,max_units=chunk))
        saved['active_seconds']+=time.monotonic()-t;saved['blocks']+=1;local_blocks+=1
        save_checkpoint(cp,saved,identity)
        write_json(root/'progress'/(stem+'.json'),dict(job=stem,status='completed' if done else 'running',blocks=saved['blocks'],active_seconds=saved['active_seconds'],resumed=resumed,**status_extract(saved['state'])))
        if done:
            data=mods[name].summarize(saved['state'],cfg)
            data={'experiment':name,'seed':seed,'config':cfg,'result':data}
            completed_write(rp,identity,data)
            return {'job':stem,'status':'completed','active_seconds':saved['active_seconds']}
        if (root/'STOP_REQUESTED').exists() or (stop_after and local_blocks>=stop_after):
            write_json(root/'progress'/(stem+'.json'),dict(job=stem,status='paused',blocks=saved['blocks'],active_seconds=saved['active_seconds'],resumed=resumed,**status_extract(saved['state'])))
            return {'job':stem,'status':'paused','active_seconds':saved['active_seconds']}

def csv_write(path,rows):
    rows=list(rows)
    if not rows:atomic_bytes(path,b'');return
    cols=list(dict.fromkeys(k for row in rows for k in row))
    import io
    buf=io.StringIO();w=csv.DictWriter(buf,fieldnames=cols);w.writeheader();w.writerows(rows)
    atomic_bytes(path,buf.getvalue().encode())

def stat(x):
    a=np.array(x,float);a=a[np.isfinite(a)];n=len(a)
    if n==0:return {'n':0,'mean':None,'ci_low':None,'ci_high':None}
    mu=float(a.mean());se=float(a.std(ddof=1)/math.sqrt(n)) if n>1 else None
    half=float(student_t.ppf(.975,n-1)*se) if n>1 else None
    return {'n':n,'mean':mu,'ci_low':None if half is None else mu-half,'ci_high':None if half is None else mu+half,'seed_min':float(a.min()),'seed_max':float(a.max())}

def generate_reports(root,plan):
    root=Path(root);records=[]
    for job in plan['jobs']:
        stem=f"{job['experiment']}_{job['seed']}";p=root/'completed'/(stem+'.json')
        if p.exists():records.append(completed_read(p,{'plan':digest(plan),'experiment':job['experiment'],'seed':job['seed'],'config':job['config']}))
    rows=[]
    for r in records:
        for x in r['result'].get('metrics',[]):rows.append({'experiment':r['experiment'],'seed':r['seed'],**x})
    csv_write(root/'METRICS.csv',rows)
    grouped=collections.defaultdict(list)
    for x in rows:
        if isinstance(x.get('value'),(int,float)) and math.isfinite(x['value']):grouped[(x['experiment'],x.get('group',''),x['arm'],x['metric'])].append(x['value'])
    means=[dict(experiment=k[0],group=k[1],arm=k[2],metric=k[3],**stat(v)) for k,v in grouped.items()]
    csv_write(root/'SUMMARY.csv',means)
    contrasts=[]
    pairs={'hybrid':[('READ-HYBRID','SLOTS'),('FULL-HYBRID','READ-HYBRID'),('FULL-HYBRID','SUPER')],
           'utility':[('UTILITY-RATE','LFU-RATE'),('UTILITY-RATE','LRU'),('UTILITY-RATE','RANDOM'),('UTILITY-RATE','SHUFFLED-UTILITY')],
           'stationarity':[('PHASE-FROZEN','PHASE-LIVE'),('PHASE-FROZEN','LAG')]}
    grouped2=collections.defaultdict(dict)
    for x in rows:
        if isinstance(x.get('value'),(int,float)) and math.isfinite(x['value']):grouped2[(x['experiment'],x.get('group',''),x['metric'])][(x['arm'],x['seed'])]=x['value']
    for key,values in grouped2.items():
        for left,right in pairs.get(key[0],[]):
            seeds=sorted({s for a,s in values if a==left}&{s for a,s in values if a==right})
            if not seeds:continue
            delta=[values[left,s]-values[right,s] for s in seeds]
            contrasts.append(dict(experiment=key[0],group=key[1],metric=key[2],contrast=left+' minus '+right,**stat(delta),values=json.dumps(delta)))
    csv_write(root/'PAIRED_CONTRASTS.csv',contrasts)
    report={'version':VERSION,'completed_jobs':len(records),'expected_jobs':len(plan['jobs']),'mode':plan['mode'],
        'interpretation':'Four seeds provide diagnostic effect estimates, not definitive qualification. Confidence intervals are pointwise exploratory paired Student intervals. Gates are not retuned.',
        'records':records,'summary':means,'paired_contrasts':contrasts}
    write_json(root/'REPORT.json',report)
    text=['**V41 mechanism closure results**','',f"Completed {len(records)}/{len(plan['jobs'])} jobs; mode: {plan['mode']}.",'',report['interpretation'],'',
        'Read DESIGN.md for locked tasks and limitations. METRICS.csv contains per-seed outcomes; PAIRED_CONTRASTS.csv preserves pairing. Each completed JSON contains validity flags and detailed diagnostics.','',
        '| Experiment | Arm | Metric | Group | Mean | Seed count |','|---|---|---|---|---:|---:|']
    for x in means:
        text.append(f"| {x['experiment']} | {x['arm']} | {x['metric']} | {x['group']} | {x['mean']:.6g} | {x['n']} |")
    atomic_bytes(root/'REPORT.md','\n'.join(text).encode()+b'\n')
    return report

def package(root):
    root=Path(root);out=root.parent/(root.name+'_results.zip')
    unfinished=len(list((root/'completed').glob('*.json')))<len(json.loads((root/'PLAN.json').read_text())['jobs'])
    files=[p for p in root.rglob('*') if p.is_file() and (unfinished or 'checkpoints' not in p.parts) and not p.name.startswith('.') and p.name!='STOP_REQUESTED' and '.tmp-' not in p.name]
    manifest={str(p.relative_to(root)):digest(p.read_bytes()) for p in files if p.name!='ARTIFACT_HASHES.json'}
    write_json(root/'ARTIFACT_HASHES.json',manifest)
    files=[p for p in files if p.name!='ARTIFACT_HASHES.json']+[root/'ARTIFACT_HASHES.json']
    tmp=out.with_suffix('.zip.tmp')
    with zipfile.ZipFile(tmp,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
        for p in sorted(files):z.write(p,str(p.relative_to(root)))
    os.replace(tmp,out)
    return out

def self_test():
    mods=load_modules();checks={}
    import tempfile
    with tempfile.TemporaryDirectory() as tmp:
        path=Path(tmp)/'completed.json';identity={'test':'json-roundtrip'}
        original={'ledger':{2:np.int64(3),10:np.array([1.,2.])}}
        completed_write(path,identity,original)
        assert completed_read(path,identity)==json.loads(canonical(original))
        bad=json.loads(path.read_text());bad['data']['ledger']['2']=4
        write_json(path,bad)
        try:completed_read(path,identity)
        except ValueError:pass
        else:raise AssertionError('Corrupted completed record accepted')
        checks['completed_json']={'numeric_key_roundtrip':True,'corruption_rejected':True}
    for name,mod in mods.items():
        checks[name]=mod.self_test()
        cfg=SMOKE_CONFIGS[name];a=mod.init_state(941101,cfg);mod.step(a,cfg,max_units=1)
        packed=pack_state(a,{'test':name});b=unpack_state(packed,{'test':name})
        mod.step(a,cfg,max_units=1);mod.step(b,cfg,max_units=1)
        assert state_fingerprint(a)==state_fingerprint(b),name+' logical resume differs'
        try:unpack_state(packed[:-1]+bytes([packed[-1]^1]),{'test':name})
        except (ValueError,zlib.error):pass
        else:raise AssertionError('Corruption accepted')
        try:unpack_state(packed,{'test':'wrong'})
        except ValueError:pass
        else:raise AssertionError('Wrong identity accepted')
        checks[name]['runner_checkpoint_resume']=True
        checks[name]['runner_corruption_rejected']=True
    return checks

def request_stop(sig,frame):
    global STOP;STOP=True

def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--out',type=Path,default=Path('v41_results'));ap.add_argument('--workers',type=int,default=1)
    ap.add_argument('--install-deps',action='store_true');ap.add_argument('--smoke',action='store_true');ap.add_argument('--self-test',action='store_true')
    ap.add_argument('--report-only',action='store_true');ap.add_argument('--stop-after-checkpoints',type=int,default=0)
    ap.add_argument('--checkpoint-records',type=int,default=32)
    args=ap.parse_args()
    if args.checkpoint_records<1 or args.workers<1 or args.stop_after_checkpoints<0:
        ap.error('workers and checkpoint-records must be positive; stop-after-checkpoints must be nonnegative')
    dependency_setup(args.install_deps);load_modules()
    if args.self_test:
        print(json.dumps(self_test(),indent=2));return
    root=args.out.resolve();root.mkdir(parents=True,exist_ok=True)
    import fcntl
    lock=(root/'.execution.lock').open('a+')
    try:fcntl.flock(lock.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
    except BlockingIOError:raise SystemExit('Another writer is using this output directory.')
    source=Path(__file__).resolve();mode='smoke' if args.smoke else 'science'
    configs=SMOKE_CONFIGS if args.smoke else CONFIGS;seeds=(941101,) if args.smoke else SEEDS
    plan={'version':VERSION,'source_sha256':digest(source.read_bytes()),'protocol_sha256':digest(PROTOCOL.encode()),'mode':mode,
          'jobs':[{'experiment':name,'seed':seed,'config':configs[name]} for name in ('utility','hybrid','stationarity') for seed in seeds]}
    pp=root/'PLAN.json'
    if pp.exists() and json.loads(pp.read_text())!=plan:raise SystemExit('Source/plan differs from saved run. Use the original script or a different output directory.')
    write_json(pp,plan);atomic_bytes(root/'DESIGN.md',PROTOCOL.encode());atomic_bytes(root/source.name,source.read_bytes())
    environment={'python':sys.version,'numpy':np.__version__,'platform':platform.platform(),'workers':args.workers}
    if not (root/'ENVIRONMENT.json').exists():write_json(root/'ENVIRONMENT.json',environment)
    write_json(root/'invocations'/(str(time.time_ns())+'.json'),dict(environment=environment,argv=sys.argv,report_only=args.report_only))
    if args.report_only:
        rep=generate_reports(root,plan);print(package(root));return
    (root/'STOP_REQUESTED').unlink(missing_ok=True)
    signal.signal(signal.SIGINT,request_stop);signal.signal(signal.SIGTERM,request_stop)
    caffeinate=None
    if sys.platform=='darwin':
        try:caffeinate=subprocess.Popen(['caffeinate','-i','-w',str(os.getpid())])
        except FileNotFoundError:pass
    jobs=[(j['experiment'],j['seed'],j['config'],str(root),digest(plan),args.checkpoint_records,args.stop_after_checkpoints) for j in plan['jobs']]
    try:
        with concurrent.futures.ProcessPoolExecutor(max_workers=max(1,args.workers)) as pool:
            futures={pool.submit(worker,j):j for j in jobs};remaining=set(futures)
            while remaining:
                done,remaining=concurrent.futures.wait(remaining,timeout=2,return_when=concurrent.futures.FIRST_COMPLETED)
                if STOP:atomic_bytes(root/'STOP_REQUESTED',b'Stop requested\n')
                for f in done:
                    try:result=f.result();print(json.dumps(result),flush=True)
                    except Exception as e:
                        atomic_bytes(root/'STOP_REQUESTED',b'Worker failure\n')
                        write_json(root/'FAILURE.json',{'job':futures[f][0:2],'error':repr(e)})
                        raise
                    generate_reports(root,plan)
        report=generate_reports(root,plan);archive=package(root)
        print(json.dumps({'completed_jobs':report['completed_jobs'],'expected_jobs':report['expected_jobs'],'results_zip':str(archive)}),flush=True)
    finally:
        if caffeinate is not None:caffeinate.terminate()
        lock.close()

if __name__=='__main__':main()
